"use client";

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";

import { cn } from "@/lib/utils";
import { controlChecked, copperRimChecked, focusRing, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Burnished RadioGroup: a column of choices with 0.75rem between them. */
function RadioGroup({
  className,
  ...props
}: WithClassName<RadioGroupPrimitive.Props>) {
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}
RadioGroup.displayName = "RadioGroup";

/**
 * Burnished RadioGroupItem: a 1.25rem circle pressed into a recessed well.
 * Chosen, it rises as the primary's cream bevel inside a copper rim and
 * shows a dark centre dot.
 */
function RadioGroupItem({
  className,
  ...props
}: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square size-5 shrink-0 rounded-full border-2 border-transparent",
        wellInset,
        "transition-[box-shadow,background-image] duration-fast ease-(--ease-out)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        controlChecked,
        copperRimChecked,
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="size-full flex items-center justify-center"
      >
        <span className="block size-2 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}
RadioGroupItem.displayName = "RadioGroupItem";

export { RadioGroup, RadioGroupItem };
